#!/usr/bin/env bash
# Question 2: DaemonSet ${Q2_DS} on edge nodes. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q2_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q2_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q2_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q2_NS}" delete daemonset "${Q2_DS}" --ignore-not-found --wait=true >/dev/null
kubectl label nodes --all node-type- >/dev/null 2>&1 || true
: "${Q2_NS}" "${Q2_STS}" "${Q2_DS}"
